function setup() {
  createCanvas(640, 640);
  noFill();
}

function draw() {
  background(255);

  let maxX = float(180)/width*(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  let maxY = float(180)/height*(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));

  translate(width/2, height/2);
  for (let i = 0; i < 360; i+=5) {
    let x = sin(radians(i)) * maxX;
    let y = cos(radians(i)) * maxY;
    push();
    translate(x, y);
    rotate(radians(i-frameCount));
    rect(0, 0, 100, 100);
    pop();

    push();
    translate(-x, -y);
    rotate(radians(i-frameCount));
    rect(0, 0, 100, 100);
    pop();
  }
}
